import re
from datetime import datetime


def dedupe_contacts(rows):
    """Normalize, deduplicate, and merge CRM contact rows.

    Takes a list of dicts (first_name, last_name, email, phone, zip, tags,
    opted_out, updated, source) and returns one merged dict per person,
    following the data team's rules.
    """

    # ---------- normalizers ----------

    def norm_email(raw):
        s = raw or ""
        m = re.search(r"<([^<>]*)>", s)          # "Ann Lee <ann@x.org>" -> "ann@x.org"
        if m:
            s = m.group(1)
        s = s.strip().lower()
        if "@" in s:
            local, domain = s.rsplit("@", 1)
            if domain in ("gmail.com", "googlemail.com"):
                local = local.split("+", 1)[0].replace(".", "")
                s = local + "@gmail.com"
        # validity: exactly one "@", non-empty local part, domain has a dot
        # and doesn't start or end with one
        if s.count("@") != 1:
            return ""
        local, domain = s.split("@")
        if not local or "." not in domain or domain.startswith(".") or domain.endswith("."):
            return ""
        return s

    def norm_phone(raw):
        s = (raw or "").lower()
        m = re.search(r"ext|x|#", s)             # cut at extension marker
        if m:
            s = s[: m.start()]
        d = re.sub(r"\D", "", s)
        if len(d) == 11 and d[0] == "1":
            d = d[1:]
        if len(d) == 10 and d[0] not in "01":
            return d
        return ""

    def norm_zip(raw):
        z = (raw or "").strip()
        if "-" in z:                             # ZIP+4 -> keep the part before the hyphen
            z = z.split("-", 1)[0].strip()
        if re.fullmatch(r"\d{4}", z):            # Excel ate the leading zero
            z = "0" + z
        return z if re.fullmatch(r"\d{5}", z) else ""

    def norm_name(raw):
        n = (raw or "").strip()
        if n.isupper() or n.islower():
            n = n.title()
        return n

    def parse_updated(raw):
        s = (raw or "").strip()
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y"):
            try:
                return datetime.strptime(s, fmt)
            except ValueError:
                pass
        raise ValueError(f"Unrecognized 'updated' value: {raw!r}")

    def is_opted_out(raw):
        return (raw or "").strip().lower() in ("y", "yes", "true", "1")

    def norm_tags(raw):
        return {t.strip().lower() for t in re.split(r"[;,]", raw or "") if t.strip()}

    # ---------- normalize rows, dropping unreachable ones (rule 9) ----------

    recs = []
    for i, r in enumerate(rows):
        email = norm_email(r.get("email", ""))
        phone = norm_phone(r.get("phone", ""))
        if not email and not phone:
            continue
        recs.append({
            "idx": i,
            "first_name": norm_name(r.get("first_name", "")),
            "last_name": norm_name(r.get("last_name", "")),
            "email": email,
            "phone": phone,
            "zip": norm_zip(r.get("zip", "")),
            "tags": norm_tags(r.get("tags", "")),
            "opted_out": is_opted_out(r.get("opted_out", "")),
            "updated": parse_updated(r.get("updated", "")),
            "source": (r.get("source", "") or "").strip().lower(),
        })

    # ---------- group rows into people (rule 10, transitive via union-find) ----------

    parent = list(range(len(recs)))

    def find(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            # keep the lower index as root so groups stay tied to earliest row
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    by_email, by_phone_last = {}, {}
    for j, rec in enumerate(recs):
        if rec["email"]:
            if rec["email"] in by_email:
                union(j, by_email[rec["email"]])
            else:
                by_email[rec["email"]] = j
        if rec["phone"] and rec["last_name"]:
            key = (rec["phone"], rec["last_name"].lower())
            if key in by_phone_last:
                union(j, by_phone_last[key])
            else:
                by_phone_last[key] = j

    groups = {}                                  # insertion order = order of earliest row (rule 12)
    for j in range(len(recs)):
        groups.setdefault(find(j), []).append(recs[j])

    # ---------- merge each group into one output dict (rule 11) ----------

    def pick(group, field):
        cands = [rec for rec in group if rec[field]]
        if not cands:
            return ""
        # prefer manual source, then most recent 'updated', then earliest input row
        best = max(cands, key=lambda rec: (rec["source"] == "manual",
                                           rec["updated"],
                                           -rec["idx"]))
        return best[field]

    out = []
    for group in groups.values():
        tags = set()
        for rec in group:
            tags |= rec["tags"]
        out.append({
            "first_name": pick(group, "first_name"),
            "last_name": pick(group, "last_name"),
            "email": pick(group, "email"),
            "phone": pick(group, "phone"),
            "zip": pick(group, "zip"),
            "source": pick(group, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(rec["opted_out"] for rec in group) else "N",
            "updated": max(rec["updated"] for rec in group).strftime("%Y-%m-%d"),
        })
    return out
```

A few notes on decisions where the rules left room:

- **Invalid email/phone** become `""` at normalization time, so they never participate in matching and never win the "pick" step — a group whose only email is malformed will output `email: ""`.
- **Phone extensions:** the cut happens at the *earliest* of `x`, `ext`, or `#`, so `"(202) 555-0199 ext. 12"` and `"2025550199x12"` both become `2025550199`.
- **Phone + last-name matching** uses the normalized (title-cased) last name, compared case-insensitively, and only when the last name is non-empty — so two rows sharing a phone but with blank last names are *not* merged.
- **`updated`** that doesn't match any of the three formats raises `ValueError` rather than silently guessing, since the spec says it's always one of those three; if that's a bad row in the export you'll want to know before the send.
- **Source preference for the `source` field itself:** "manual" also wins there, so a group with one manual row will report `source: "manual"`.

Before tomorrow's send, I'd suggest a quick sanity check on the output: count rows with `opted_out == "Y"` (those should be excluded from the send list), and spot-check a few gmail merges, since that's where most of the duplicates usually hide.
